INSERT INTO bridging.notes (id, topic_id, subtopic_name, summary, key_concepts, formulas, worked_examples, common_mistakes, exam_tips, related_topic_codes, order_index, level_band, recommended_levels, curriculum_stage, strand, estimated_minutes, revision_status, created_at, updated_at) VALUES ('019fa780-0e85-7115-8248-b56954b32be6'::uuid, '019f9df7-a2a2-78fc-bd9e-a40e9b4f9363'::uuid, 'Volume and surface area of solids', 'Volume fills a solid, surface area covers it. Curved surface area is the part most often forgotten.', ARRAY['Prism volume is always cross-sectional area times length', 'Cones and pyramids include a factor of one third', 'Total surface area means every face, including the base if it is closed']::text[], ARRAY['{"note":"Add two circles for a closed cylinder.","label":"Cylinder","expression":"volume = pi r^2 h, curved surface = 2 pi r h"}'::jsonb, '{"note":"l is the slant height, found with Pythagoras.","label":"Cone","expression":"volume = 1/3 pi r^2 h, curved surface = pi r l"}'::jsonb, '{"note":"A hemisphere is half the volume plus a flat circle.","label":"Sphere","expression":"volume = 4/3 pi r^3, surface area = 4 pi r^2"}'::jsonb]::text[], ARRAY['{"steps":["Volume = 1/3 pi r^2 h","= 1/3 x pi x 9 x 8","= 24 pi"],"answer":"75.4 cm^3 to 3 significant figures","question":"Find the volume of a cone of radius 3 cm and vertical height 8 cm."}'::jsonb]::text[], ARRAY['{"fix":"Volume uses the vertical height. Slant height is only for curved surface area.","mistake":"Using the slant height in the cone volume formula."}'::jsonb, '{"fix":"Any solid that tapers to a point needs the one third factor.","mistake":"Omitting the one third for cones and pyramids."}'::jsonb]::text[], ARRAY['Decide whether the solid is open or closed before totalling surface area.', 'Volume answers use cubic units, surface area uses squared units.']::text[], ARRAY['t12']::text[], 1302, NULL, NULL, 'O-Level', NULL, NULL, 'published', NULL::timestamptz, '2026-07-28T06:53:35.236Z'::timestamptz) ON CONFLICT (id) DO NOTHING;
INSERT INTO bridging.notes (id, topic_id, subtopic_name, summary, key_concepts, formulas, worked_examples, common_mistakes, exam_tips, related_topic_codes, order_index, level_band, recommended_levels, curriculum_stage, strand, estimated_minutes, revision_status, created_at, updated_at) VALUES ('019fa780-0e85-712d-a090-4b3d82b18a9b'::uuid, '019f9df7-a2a2-790d-b90f-3e453f40cd4c'::uuid, 'Coordinate geometry', 'The Cartesian plane uses perpendicular x- and y-axes meeting at the origin (0, 0). Points, midpoints and distances are the basic tools.', ARRAY['A point is written (x, y); the origin is (0, 0)', 'Read scales carefully: each small square may represent 1 unit or a fraction of a unit', 'Distance between two points comes from Pythagoras on the coordinate differences', 'Midpoint is the average of the x-coordinates and of the y-coordinates']::text[], ARRAY['{"note":"Average each coordinate separately.","label":"Midpoint","expression":"((x1 + x2)/2, (y1 + y2)/2)"}'::jsonb, '{"note":"Same as length of the line segment joining the points.","label":"Distance","expression":"sqrt((x2 - x1)^2 + (y2 - y1)^2)"}'::jsonb]::text[], ARRAY['{"steps":["Left of the origin means negative x","Above the origin means positive y"],"answer":"(-4, 7)","question":"A point is 4 units left of the origin and 7 units above it. State its coordinates."}'::jsonb, '{"steps":["y difference = -9 - (-5) = -4; x difference = -1 - 3 = -4","Distance = sqrt((-4)^2 + (-4)^2) = sqrt(32) = 5.66 units (3 s.f.)"],"answer":"5.66 units (3 s.f.)","question":"Find the distance between A(3, -5) and B(-1, -9)."}'::jsonb]::text[], ARRAY['{"fix":"Midpoint means average: add and divide by two.","mistake":"Subtracting coordinates when finding a midpoint."}'::jsonb, '{"fix":"Check what each small square represents before reading coordinates.","mistake":"Misreading the grid scale when plotting or reading a point."}'::jsonb]::text[], ARRAY['Always label the x-axis and y-axis on sketches.', 'Plot points roughly to sanity-check distance and midpoint answers.']::text[], ARRAY['t05']::text[], 1401, NULL, NULL, 'O-Level', NULL, NULL, 'published', NULL::timestamptz, '2026-07-28T06:53:35.236Z'::timestamptz) ON CONFLICT (id) DO NOTHING;
INSERT INTO bridging.notes (id, topic_id, subtopic_name, summary, key_concepts, formulas, worked_examples, common_mistakes, exam_tips, related_topic_codes, order_index, level_band, recommended_levels, curriculum_stage, strand, estimated_minutes, revision_status, created_at, updated_at) VALUES ('019fa780-0e85-714b-8123-58667f21b215'::uuid, '019f9df7-a2a2-791f-bec6-372d238905de'::uuid, 'Vectors in two dimensions', 'A vector has magnitude and direction. Add by the triangle/parallelogram law, and use column vectors for components.', ARRAY['Vector AB means go from A to B; BA = -AB', 'Triangle law: AB + BC = AC; subtract by adding the negative', 'Parallel vectors are scalar multiples; collinear points have AB = k AC', 'Magnitude of column vector (x / y) is sqrt(x^2 + y^2)']::text[], ARRAY['{"note":"For the column vector (x / y).","label":"Magnitude","expression":"|v| = sqrt(x^2 + y^2)"}'::jsonb, '{"note":"Destination minus start.","label":"Displacement","expression":"AB = position of B - position of A"}'::jsonb]::text[], ARRAY['{"steps":["|BA| = sqrt(8^2 + (-6)^2) = 10","Position of A - BA = position of B: (-9 / 2) - (8 / -6) = (-17 / 8), so B = (-17, 8)","(m / -3) = k(8 / -6); k = (-3)/(-6) = 1/2, so m = 4"],"answer":"|BA| = 10; B = (-17, 8); m = 4","question":"A is (-9, 2) and BA = (8 / -6). Find |BA|, the coordinates of B, and m if CD = (m / -3) is parallel to BA."}'::jsonb]::text[], ARRAY['{"fix":"AB = b - a (end minus start).","mistake":"Writing AB as a - b when OA = a and OB = b."}'::jsonb, '{"fix":"Add the components first, then apply the magnitude formula.","mistake":"Adding magnitudes to get the magnitude of a sum."}'::jsonb]::text[], ARRAY['Draw arrows on the diagram for every vector you write down.', 'If two vectors are parallel, write one as k times the other and solve for k.']::text[], ARRAY['t12']::text[], 1501, NULL, NULL, 'O-Level', NULL, NULL, 'published', NULL::timestamptz, '2026-07-28T06:53:35.236Z'::timestamptz) ON CONFLICT (id) DO NOTHING;
INSERT INTO bridging.notes (id, topic_id, subtopic_name, summary, key_concepts, formulas, worked_examples, common_mistakes, exam_tips, related_topic_codes, order_index, level_band, recommended_levels, curriculum_stage, strand, estimated_minutes, revision_status, created_at, updated_at) VALUES ('019fa780-0e85-71ab-b016-3c60cee766c0'::uuid, '019f9df7-a2a2-7930-a717-cd252273c91f'::uuid, 'Averages and measures of spread', 'Mean, median and mode summarise a data set differently. Range is the simplest measure of spread for ungrouped data.', ARRAY['Mean = sum of observations / number of observations', 'Mode is the most frequent value', 'Median is the middle value after ordering; for an even count, average the two middle values', 'Range = largest value - smallest value']::text[], ARRAY['{"note":"N is the number of observations.","label":"Mean (ungrouped)","expression":"mean = (sum of x) / N"}'::jsonb, '{"note":"For even N, average the values at N/2 and N/2 + 1.","label":"Median position (odd N)","expression":"position = (N + 1) / 2"}'::jsonb]::text[], ARRAY['{"steps":["Order: 1, 2, 3, 5, 9","N = 5 (odd), so position = (5 + 1) / 2 = 3","Median is the 3rd value"],"answer":"3","question":"Find the median of 9, 5, 3, 1, 2."}'::jsonb, '{"steps":["Already ordered; N = 6","Middle positions 3 and 4: values 8 and 10","Median = (8 + 10) / 2 = 9"],"answer":"9","question":"Find the median of 2, 4, 8, 10, 12, 15."}'::jsonb]::text[], ARRAY['{"fix":"Always sort into ascending order first.","mistake":"Finding the median without ordering the data."}'::jsonb, '{"fix":"The mode is the value that appears most often.","mistake":"Calling every common value a mode without checking frequency."}'::jsonb]::text[], ARRAY['State whether you used mean, median or mode, and give units when relevant.', 'If outliers matter, the median is usually more representative than the mean.']::text[], ARRAY['t17']::text[], 1601, NULL, NULL, 'O-Level', NULL, NULL, 'published', NULL::timestamptz, '2026-07-28T06:53:35.236Z'::timestamptz) ON CONFLICT (id) DO NOTHING;
INSERT INTO bridging.notes (id, topic_id, subtopic_name, summary, key_concepts, formulas, worked_examples, common_mistakes, exam_tips, related_topic_codes, order_index, level_band, recommended_levels, curriculum_stage, strand, estimated_minutes, revision_status, created_at, updated_at) VALUES ('019fa799-85bc-7e0f-b6c8-3e8869a04a9e'::uuid, '019f9df7-a2a2-7930-a717-cd252273c91f'::uuid, 'Standard deviation and comparing data sets', 'Standard deviation measures spread about the mean. Use mean and SD together to compare two data sets in context.', ARRAY['Larger SD means values are more spread out / less consistent', 'For grouped data, use class mid-points with frequencies', 'Compare average (mean) and spread (SD) separately, using the question context']::text[], ARRAY['{"note":"Equivalent to sqrt(mean of squares - square of mean).","label":"SD (ungrouped)","expression":"s.d. = sqrt( sum((x - mean)^2) / N )"}'::jsonb, '{"note":"x is the mid-point of each class. Write ''standard deviation'' in full in answers.","label":"Mean and SD (grouped)","expression":"mean = sum(fx)/sum(f); s.d. = sqrt( sum(f x^2)/sum(f) - (mean)^2 )"}'::jsonb]::text[], ARRAY['{"steps":["Mean = 23/5 = 4.6","Sum of (x - mean)^2 = 53.2","s.d. = sqrt(53.2 / 5) = 3.26 (3 s.f.)"],"answer":"3.26 (3 s.f.)","question":"Find the standard deviation of 5, 0, 9, 7, 2."}'::jsonb, '{"steps":["sum(f) = 82; mean = sum(fx)/82 ≈ 71.5","s.d. = sqrt( mean of squares - square of mean ) ≈ 12.2 (3 s.f.)"],"answer":"Mean about 71.5; standard deviation 12.2 (3 s.f.)","question":"Grouped marks with mid-points 55,65,75,85,95 and frequencies 15,28,18,13,8. Find mean and SD."}'::jsonb]::text[], ARRAY['{"fix":"It is mean of the squares minus the square of the mean (never negative).","mistake":"Subtracting in the wrong order inside the square root."}'::jsonb, '{"fix":"Mention both the average and the spread for full marks.","mistake":"Comparing two data sets using the mean alone."}'::jsonb]::text[], ARRAY['Set out a table of mid-point x, f, fx and f x^2 before substituting.', 'A smaller standard deviation means more consistent results in context.']::text[], ARRAY['t17']::text[], 1602, NULL, NULL, 'O-Level', NULL, NULL, 'published', NULL::timestamptz, '2026-07-28T07:21:24.153Z'::timestamptz) ON CONFLICT (id) DO NOTHING;